script:
(function () {
  'use strict';
  // Debt service coverage ratio = net operating income / annual debt service.
  //   Property NOI = gross rent x (1 - vacancy %) + other income - operating expenses.
  //   Business cash available = EBITDA - cash taxes - capital spending - owner draws.
  //   Annual debt service = 12 x new loan payment + other annual debt payments, where the
  //   payment is rL / (1 - (1 + r)^-n) (L / n at 0%), or rL when interest-only.
  //   Maximum new loan at the target = present value of (NOI / target - other debt) / 12 a month
  //   over the amortization: P(1 - (1 + r)^-n) / r (P x n at 0%; P / r when interest-only).
  // Verified (scratchpad tests/b3debt/ds.test.js):
  //   $100,000 at 6% over 30 years -> $599.55 a month (standard published value);
  //   default property: NOI = 120,000 x 0.95 - 42,000 = $72,000; $750,000 at 6.75% over 25 years
  //   = $5,181.84 a month (closed form), $62,182.04 a year, DSCR 1.16; maximum loan at 1.25x =
  //   PV of $4,800 a month = $694,734, and feeding that loan back in gives 1.25x;
  //   interest-only $750,000 at 6.75% = $50,625 a year; 0% rate -> payment = L / n;
  //   no debt -> "No debt to cover" instead of dividing by zero.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function num(id) { var v = document.getElementById(id).value; return v.trim() === '' ? NaN : parseFloat(v); }
  function optNum(id) { var v = document.getElementById(id).value; return v.trim() === '' ? 0 : parseFloat(v); }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function monthlyPayment(loan, annualRate, years, io) {
    var r = annualRate / 12, n = years * 12;
    if (loan <= 0) return 0;
    if (io) return loan * r;
    return r === 0 ? loan / n : loan * r / (1 - Math.pow(1 + r, -n));
  }

  // Largest loan whose payment is `monthly`; Infinity when interest-only at 0%.
  function maxLoan(monthly, annualRate, years, io) {
    var r = annualRate / 12, n = years * 12;
    if (monthly <= 0) return 0;
    if (io) return r === 0 ? Infinity : monthly / r;
    return r === 0 ? monthly * n : monthly * (1 - Math.pow(1 + r, -n)) / r;
  }

  function ratioText(x) { return x.toFixed(2) + 'x'; }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }

  function fail(message) {
    var error = document.getElementById('dsError');
    error.hidden = false; error.textContent = message;
    ['dsRatio', 'dsMaxLoan', 'dsNoi', 'dsService', 'dsLine1', 'dsLine2', 'dsCashFlow', 'dsNeeded'].forEach(function (id) { set(id, '–'); });
    ['dsRatioNote', 'dsMaxNote', 'dsServiceNote'].forEach(function (id) { set(id, ''); });
    document.getElementById('dsNote').hidden = true;
    clearBody('dsRates');
  }

  function update() {
    var type = document.getElementById('dsType').value;
    var business = type === 'business';
    document.getElementById('dsPropertyWrap').hidden = business;
    document.getElementById('dsBusinessWrap').hidden = !business;
    var noi, line1, line2;
    if (business) {
      var ebitda = num('dsEbitda'), tax = optNum('dsTax'), capex = optNum('dsCapex'), draws = optNum('dsDraws');
      if (isNaN(ebitda) || Math.abs(ebitda) > 1e11 || [tax, capex, draws].some(function (v) { return isNaN(v) || v < 0; })) {
        fail('Enter the business EBITDA, and taxes, capital spending and draws of $0 or more.'); return;
      }
      line1 = ebitda; line2 = tax + capex + draws; noi = line1 - line2;
      set('dsIncomeLabel', 'Cash available for debt service');
      set('dsLine1Term', 'EBITDA'); set('dsLine2Term', 'Taxes, capital spending and draws');
    } else {
      var rent = num('dsRent'), vacancy = optNum('dsVacancy'), other = optNum('dsOther'), opex = optNum('dsOpex');
      if (isNaN(rent) || rent < 0 || rent > 1e11 || isNaN(vacancy) || vacancy < 0 || vacancy > 100 ||
          isNaN(other) || other < 0 || isNaN(opex) || opex < 0) {
        fail('Enter rent, other income and expenses of $0 or more and a vacancy rate from 0 to 100%.'); return;
      }
      line1 = rent * (1 - vacancy / 100) + other; line2 = opex; noi = line1 - line2;
      set('dsIncomeLabel', 'Net operating income');
      set('dsLine1Term', 'Effective income after vacancy'); set('dsLine2Term', 'Operating expenses');
    }
    var loan = optNum('dsLoan'), rate = num('dsRate'), years = num('dsYears'), existing = optNum('dsExisting'), target = num('dsTarget');
    var io = document.getElementById('dsIo').checked;
    document.getElementById('dsYears').disabled = io;
    if (isNaN(loan) || loan < 0 || loan > 1e11 || isNaN(rate) || rate < 0 || rate > 30 || isNaN(existing) || existing < 0) {
      fail('Enter a loan amount and other debt payments of $0 or more and an interest rate from 0 to 30%.'); return;
    }
    if (!io && (isNaN(years) || years < 1 || years > 40)) { fail('Enter an amortization period of 1 to 40 years.'); return; }
    if (io && (isNaN(years) || years < 1)) years = 25;
    if (isNaN(target) || target < 0.5 || target > 5) { fail('Enter a target DSCR from 0.5 to 5.'); return; }
    var error = document.getElementById('dsError');
    error.hidden = true; error.textContent = '';

    var monthly = monthlyPayment(loan, rate / 100, years, io);
    var service = monthly * 12 + existing;
    var note = document.getElementById('dsNote');
    set('dsNoi', money.format(noi));
    set('dsLine1', money.format(line1));
    set('dsLine2', '−' + money.format(line2));
    set('dsService', money.format(service));
    set('dsServiceNote', loan > 0 ? 'New loan ' + money.format(monthly) + ' a month' + (io ? ', interest only' : '') + (existing > 0 ? ', plus other debt.' : '.') : 'Other debt only.');
    set('dsCashFlow', money.format(noi - service));

    if (service <= 0) {
      set('dsRatio', 'No debt');
      set('dsRatioNote', 'Enter a loan or other debt payments to see the ratio.');
      set('dsNeeded', '–');
    } else {
      var ratio = noi / service;
      set('dsRatio', ratioText(ratio));
      set('dsRatioNote', ratio >= target - 1e-9 ? 'Meets your ' + ratioText(target) + ' minimum.'
        : (ratio < 1 ? 'Below 1.00x: income does not cover the payments.' : 'Below your ' + ratioText(target) + ' minimum.'));
      set('dsNeeded', money.format(service * target));
    }

    var room = noi / target - existing;
    var max = maxLoan(room / 12, rate / 100, years, io);
    if (max === Infinity) { set('dsMaxLoan', 'No limit'); set('dsMaxNote', 'An interest-only loan at 0% has no payments to cover.'); }
    else {
      set('dsMaxLoan', whole.format(Math.floor(max)));
      set('dsMaxNote', room <= 0 ? 'Your income does not cover any new debt at this target.'
        : (loan > 0 ? (max >= loan ? whole.format(Math.floor(max - loan)) + ' more than you entered.' : whole.format(Math.ceil(loan - max)) + ' less than you entered.')
          : 'Based on ' + money.format(room / 12) + ' a month of payments.'));
    }
    note.hidden = noi > 0;
    if (noi <= 0) note.textContent = 'Income after expenses is zero or negative, so it cannot support any debt payments.';

    var body = clearBody('dsRates');
    [-1, -0.5, 0, 0.5, 1, 1.5].forEach(function (delta) {
      var r = Math.round((rate + delta) * 1000) / 1000;
      if (r < 0 || r > 30) return;
      var m = monthlyPayment(loan, r / 100, years, io), s = m * 12 + existing, mx = maxLoan(room / 12, r / 100, years, io);
      addRow(body, [r.toFixed(3).replace(/\.?0+$/, '') + '%' + (delta === 0 ? ' (yours)' : ''), money.format(m),
        s > 0 ? ratioText(noi / s) : 'No debt', mx === Infinity ? 'No limit' : whole.format(Math.floor(mx))]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('dsForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
